import { HiMail, HiPhone } from "react-icons/hi";

const Contacts = () => {
  const formHandler = (e) => {
    e.preventDefault();
    alert("Your inquiry has been received. A member of the team will be in touch shortly.");
  };

  return (
    <section id="contact" className="mx-auto max-w-7xl px-4 py-24 sm:px-6 lg:px-8">
      <div className="grid gap-8 rounded-[2rem] border border-white/10 bg-slate-900/70 p-8 shadow-glow lg:grid-cols-[1.1fr_0.9fr] lg:p-12">
        <div>
          <p className="text-sm uppercase tracking-[0.35em] text-amber-300">Reserve your stay</p>
          <h2 className="mt-3 text-3xl font-semibold text-white sm:text-4xl">Begin your next chapter in calm luxury.</h2>
          <p className="mt-5 max-w-xl text-lg text-slate-300">
            Share your preferred dates and preferences, and our team will curate the ideal experience for you.
          </p>
          <div className="mt-8 space-y-3 text-slate-200">
            <div className="flex items-center gap-3"><HiPhone /> +1 (555) 014-2890</div>
            <div className="flex items-center gap-3"><HiMail /> stay@pacesworldwide.com</div>
          </div>
        </div>

        <form onSubmit={formHandler} className="space-y-4 rounded-[1.5rem] border border-white/10 bg-black/20 p-6" noValidate>
          <div>
            <label htmlFor="name" className="mb-2 block text-sm font-medium text-slate-200">Full name</label>
            <input id="name" name="name" type="text" className="w-full rounded-2xl border border-white/10 bg-white/10 px-4 py-3 text-white outline-none ring-0 placeholder:text-slate-400 focus:border-amber-300" placeholder="Jordan Rivera" />
          </div>
          <div>
            <label htmlFor="email" className="mb-2 block text-sm font-medium text-slate-200">Email address</label>
            <input id="email" name="email" type="email" className="w-full rounded-2xl border border-white/10 bg-white/10 px-4 py-3 text-white outline-none placeholder:text-slate-400 focus:border-amber-300" placeholder="you@example.com" />
          </div>
          <div>
            <label htmlFor="message" className="mb-2 block text-sm font-medium text-slate-200">Tell us about your stay</label>
            <textarea id="message" name="message" rows="6" className="w-full rounded-2xl border border-white/10 bg-white/10 px-4 py-3 text-white outline-none placeholder:text-slate-400 focus:border-amber-300" placeholder="Preferred dates, room type, special requests..." />
          </div>
          <button type="submit" className="rounded-full bg-amber-400 px-6 py-3 font-semibold text-slate-950 transition hover:bg-amber-300">Send Inquiry</button>
        </form>
      </div>
    </section>
  );
};

export default Contacts;
